import React, { useEffect, useRef } from 'react';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';

const MapSection = () => {
  const mapRef = useRef(null);
  const mapInstanceRef = useRef(null);

  useEffect(() => {
    if (mapRef.current && !mapInstanceRef.current) {
      // Initialize the map
      mapInstanceRef.current = L.map(mapRef.current).setView([40.7128, -74.0060], 12);

      // Add tile layer
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap contributors'
      }).addTo(mapInstanceRef.current);

      // Risk zones data
      const riskZones = [
        {
          coords: [[40.7200, -74.0100], [40.7250, -74.0050], [40.7220, -74.0020], [40.7170, -74.0070]],
          risk: 'high',
          label: 'FLOOD',
          color: '#ef4444'
        },
        {
          coords: [[40.7080, -74.0150], [40.7120, -74.0100], [40.7100, -74.0080], [40.7060, -74.0130]],
          risk: 'critical',
          label: 'FIRE',
          color: '#dc2626'
        },
        {
          coords: [[40.7150, -73.9980], [40.7200, -73.9930], [40.7180, -73.9900], [40.7130, -73.9950]],
          risk: 'safe',
          label: 'SAFE',
          color: '#22c55e'
        }
      ];

      // Add risk zones to map
      riskZones.forEach(zone => {
        const polygon = L.polygon(zone.coords, {
          color: zone.color,
          fillColor: zone.color,
          fillOpacity: 0.3,
          weight: 2
        }).addTo(mapInstanceRef.current);

        // Add popup
        polygon.bindPopup(`
          <div class="text-black">
            <strong>${zone.label}</strong><br>
            Risk Level: ${zone.risk.toUpperCase()}<br>
            Status: Active Monitoring
          </div>
        `);
      });

      // Add markers for specific incidents
      const incidents = [
        {
          coords: [40.7200, -74.0075],
          type: 'Building Collapse',
          severity: 'Critical',
          icon: '🏢'
        },
        {
          coords: [40.7100, -74.0125],
          type: 'Fire Incident',
          severity: 'High',
          icon: '🔥'
        }
      ];

      incidents.forEach(incident => {
        const marker = L.marker(incident.coords).addTo(mapInstanceRef.current);
        marker.bindPopup(`
          <div class="text-black">
            <strong>${incident.type}</strong><br>
            Severity: ${incident.severity}<br>
            Status: Response Active
          </div>
        `);
      });
    }

    return () => {
      if (mapInstanceRef.current) {
        mapInstanceRef.current.remove();
        mapInstanceRef.current = null;
      }
    };
  }, []);

  return (
    <div className="relative h-full">
      {/* Map Container */}
      <div ref={mapRef} className="w-full h-full" />
      
      {/* Map Legend */}
      <div className="absolute top-4 left-4 bg-gray-800 bg-opacity-90 rounded-lg p-4 z-[1000]">
        <h4 className="text-white font-semibold mb-3">Disaster Zone Map</h4>
        <p className="text-gray-300 text-sm mb-3">Real-time satellite analysis & route optimization</p>
        
        <div className="space-y-2">
          <div className="flex items-center space-x-2">
            <div className="w-4 h-4 bg-red-500 rounded"></div>
            <span className="text-white text-sm">High Risk</span>
          </div>
          <div className="flex items-center space-x-2">
            <div className="w-4 h-4 bg-orange-500 rounded"></div>
            <span className="text-white text-sm">Medium Risk</span>
          </div>
          <div className="flex items-center space-x-2">
            <div className="w-4 h-4 bg-green-500 rounded"></div>
            <span className="text-white text-sm">Safe Zone</span>
          </div>
        </div>
      </div>

      {/* Processing Indicator */}
      <div className="absolute top-4 right-4 bg-gray-800 bg-opacity-90 rounded-lg p-3 z-[1000]">
        <div className="flex items-center space-x-2">
          <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></div>
          <span className="text-white text-sm">Processing satellite data...</span>
        </div>
      </div>
    </div>
  );
};

export default MapSection;
